import{_ as o,o as u,c as q,ag as e}from"./chunks/framework.CAXxHpAX.js";const d=JSON.parse('{"title":"金刚经7分-整体观是非对错","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经7分-整体观是非对错.md","filePath":"60-原文段落/金刚经7分-整体观是非对错.md","lastUpdated":null}'),p={name:"60-原文段落/金刚经7分-整体观是非对错.md"};function a(_,t,r,s,n,c){return u(),q("div",null,[...t[0]||(t[0]=[e('<h1 id="金刚经7分-整体观是非对错" tabindex="-1">金刚经7分-整体观是非对错 <a class="header-anchor" href="#金刚经7分-整体观是非对错" aria-label="Permalink to &quot;金刚经7分-整体观是非对错&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/7了空居士讲《金刚经》-第七分无得无说分20161014">7了空居士讲《金刚经》-第七分无得无说分20161014</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>【答疑】</strong></p><p>**2.****问：**我看很多的人在看了这个&quot;无有定法&quot;，跟这个&quot;皆不可取，不可说&quot;这样的一种说法，他们有一种观念，就是说，世上没有是非对错善恶，那么师父认为他们的这种看法是否正确？</p><p>**了空居士：**我告诉你，这些人是将&quot;理&quot;和&quot;事&quot;，给搞成一团了。唉，这些人是没有开悟的人，其实社会上很多人都是误入了这个歧途，这个误是错误的误，不是开悟的悟，&quot;误入歧途&quot;。 嗯，他其实误入哪个歧途？就是&quot;空&quot;，着空了，&quot;空有两边&quot;，他离了&quot;有&quot;又着了&quot;空&quot;， 他以为什么东西都是不存在的，那不存在，我打你一棒看存不存在，是不是啊？嗯，就是这个道理，他这个就是着了&quot;空&quot;。其实世上是有&quot;是非对错&quot;的，只是&quot;是非对错&quot;它也是因为不同的时间不同的条件而改变。但是从总体上来说，任何一个时空点的&quot;是非对错&quot;还是有一定的标准的，这就是整体观，整体观。</p><p>就好像说...好像以前人家说，唉呀，你们什么都要忍啊，我说那么日本鬼子侵略我们，我们也要忍了，是不是？他们还以为来帮助我们呢。站在他们立场上，他们宣传是在帮助我们这些落后的民族，那其实他们是侵略人家嘛。站在我们的立场上是侵略人家，站在他们的立场上，他们还大言不惭，说他们是在帮助落后的民族。那好了啊，那这个...他们就说他们是对的，我们就说他是错的，那么说唉呀这个就扯不平了。扯不平怎么办？我们就站在同样是人类这个总体的立场上，你真的来帮助我们，你有钱就拿过来了，有东西就送给我们，就好像我们去救灾一样嘛，这就是帮助人啊，你是来这里杀啊抢啊做坏事啊欺负人啊，你还说帮助人？是不是啊？嗯，从总体上，反过来，那我去杀你去抢你你要不要？我去帮助你好不好？如果你不要，那就说明你这种帮助是假的是错误的嘛。所以儒家有一句话&quot;己所不欲，勿施与人&quot;啊。那么你说唉呀，那我以后有东西就不能送给别人？不是！你送给别人的东西，其实往往是你自己觉得还是有用的啊，你才会去送给别人，你不会将垃圾提到人家家里去吧，是不是啊？所以这个就是说，在任何一个时空点，还是有&quot;是非对错&quot;的，你要按照当时当地的这种整体观来衡量。</p><p>**主持：**那也就是说，所以说没有一个绝对的放之四海皆准的是非对错的标准，但是在某一个具体的情景下，这个还是有是非对错的标准。</p><p>**了空居士：**对对。</p><p>**主持：**也就是实际上也就是&quot;无有定法&quot;这个意思了。</p><p>**了空居士：**对，实际上还是有&quot;法&quot;，有相对的&quot;法&quot;，没有绝对的&quot;法&quot;啊。</p><p>**主持：**也就解释了这个&quot;一切贤圣皆以无为法而有差别&quot;，其实也在讲这个意思。</p><p>**了空居士：**对对，&quot;无为法&quot;， 就是他没有带着任何主观的想法，都是按照客观的实际，去那里具体问题具体分析嘛，是这个意思。</p><p>**主持：**那最后一个就是&quot;一切贤圣皆以无为法而有差别&quot;，那我们跟这些贤圣——就说我们这些没有大彻大悟的人，还在学习的人——跟这&quot;一切贤圣&quot;的这个具体的行为，我们的跟他们的差距在哪里呢？</p><p>**了空居士：**哈，就是&quot;有为&quot;和&quot;无为&quot;，我们是有为法而有差别，就是老是站在自己的立场上去看别人啊，&quot;无为法&quot;就是说它是以最客观、最平等、最亲近这个心态去看待事情，是这样的。</p>',15)])])}const i=o(p,[["render",a]]);export{d as __pageData,i as default};
